BEGIN;
CREATE TABLE IF NOT EXISTS suppliers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE CHECK(code~'^[A-Z0-9]{2,6}$'),name text NOT NULL,country text NOT NULL DEFAULT '',currency text NOT NULL DEFAULT 'AED',contact text NOT NULL DEFAULT '',email text NOT NULL DEFAULT '',notes text NOT NULL DEFAULT '',active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name_ar text NOT NULL,name_en text NOT NULL,slug text NOT NULL UNIQUE CHECK(slug~'^[a-z0-9-]{1,80}$'),position integer NOT NULL DEFAULT 0,active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS coding_terms(dimension text NOT NULL CHECK(dimension IN('style','color','length','sleeve')),code text NOT NULL CHECK(code~'^[A-Z]$'),name_ar text NOT NULL,name_en text NOT NULL,PRIMARY KEY(dimension,code));
CREATE SEQUENCE IF NOT EXISTS product_number_seq;
ALTER TABLE products ADD COLUMN IF NOT EXISTS sku text UNIQUE;
ALTER TABLE products ADD COLUMN IF NOT EXISTS supplier_id uuid REFERENCES suppliers(id);
ALTER TABLE products ADD COLUMN IF NOT EXISTS category_id uuid REFERENCES categories(id);
ALTER TABLE products ADD COLUMN IF NOT EXISTS style_code text;
ALTER TABLE products ADD COLUMN IF NOT EXISTS color_code text;
ALTER TABLE products ADD COLUMN IF NOT EXISTS year integer;
ALTER TABLE products ADD COLUMN IF NOT EXISTS length_code text;
ALTER TABLE products ADD COLUMN IF NOT EXISTS sleeve_code text;
ALTER TABLE products ADD COLUMN IF NOT EXISTS images jsonb NOT NULL DEFAULT '[]';
ALTER TABLE products ADD COLUMN IF NOT EXISTS option_groups jsonb NOT NULL DEFAULT '[]';
ALTER TABLE products ADD COLUMN IF NOT EXISTS tags jsonb NOT NULL DEFAULT '[]';
ALTER TABLE products ADD COLUMN IF NOT EXISTS details jsonb NOT NULL DEFAULT '{}';
ALTER TABLE products ADD COLUMN IF NOT EXISTS archived boolean NOT NULL DEFAULT false;
ALTER TABLE products ADD COLUMN IF NOT EXISTS version integer NOT NULL DEFAULT 1;
ALTER TABLE products ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE products ADD COLUMN IF NOT EXISTS max_per_order integer NOT NULL DEFAULT 50 CHECK(max_per_order BETWEEN 1 AND 50);
ALTER TABLE variants ADD COLUMN IF NOT EXISTS sku text UNIQUE;
ALTER TABLE variants ADD COLUMN IF NOT EXISTS options jsonb NOT NULL DEFAULT '{}';
ALTER TABLE variants ADD COLUMN IF NOT EXISTS barcode text NOT NULL DEFAULT '';
ALTER TABLE variants ADD COLUMN IF NOT EXISTS sale_price_cents bigint CHECK(sale_price_cents>=0);
ALTER TABLE variants ADD COLUMN IF NOT EXISTS sale_start timestamptz;
ALTER TABLE variants ADD COLUMN IF NOT EXISTS sale_end timestamptz;
ALTER TABLE variants ADD COLUMN IF NOT EXISTS low_stock_threshold integer NOT NULL DEFAULT 2 CHECK(low_stock_threshold>=0);
ALTER TABLE variants ADD COLUMN IF NOT EXISTS active boolean NOT NULL DEFAULT true;
ALTER TABLE variants ADD COLUMN IF NOT EXISTS cost_parts jsonb NOT NULL DEFAULT '{}';
CREATE TABLE IF NOT EXISTS stock_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),variant_id uuid NOT NULL REFERENCES variants(id),on_hand_delta integer NOT NULL DEFAULT 0,reserved_delta integer NOT NULL DEFAULT 0,reason text NOT NULL,reference text NOT NULL DEFAULT '',created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE finance_entries ADD COLUMN IF NOT EXISTS occurred_on date NOT NULL DEFAULT CURRENT_DATE;
ALTER TABLE finance_entries ADD COLUMN IF NOT EXISTS category text NOT NULL DEFAULT '';
ALTER TABLE finance_entries ADD COLUMN IF NOT EXISTS account text NOT NULL DEFAULT '';
ALTER TABLE finance_entries ADD COLUMN IF NOT EXISTS reference text NOT NULL DEFAULT '';
CREATE TABLE IF NOT EXISTS payment_settlements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL UNIQUE REFERENCES orders(id),gross_cents bigint NOT NULL CHECK(gross_cents>=0),fee_cents bigint NOT NULL CHECK(fee_cents>=0),fee_tax_cents bigint NOT NULL CHECK(fee_tax_cents>=0),net_cents bigint NOT NULL CHECK(net_cents>=0 AND net_cents=gross_cents-fee_cents-fee_tax_cents),bank_date date,reference text NOT NULL,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS operational_settings(id integer PRIMARY KEY CHECK(id=1),settings jsonb NOT NULL,updated_by text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS variants_product_active ON variants(product_id) WHERE active;
CREATE INDEX IF NOT EXISTS orders_payment_deadline ON orders(payment_expires_at) WHERE status='awaiting_payment';
CREATE INDEX IF NOT EXISTS movements_variant_created ON stock_movements(variant_id,created_at DESC);
CREATE INDEX IF NOT EXISTS ledger_occurred_kind ON finance_entries(occurred_on,kind);
CREATE TABLE IF NOT EXISTS operation_requests(id uuid PRIMARY KEY,actor text NOT NULL,action text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
COMMIT;
